INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(10382,0,0,'%s collapses but the broken body rises again!',16,0,100.0,0,0,0,'Mangled Cadaver'),
(10405,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'Plague Ghoul'),
(10411,0,0,'The living are here!',14,0,100.0,0,0,6596,'Eye of Naxxramas'),
(10813,0,0,'You fools think you can defeat me so easily? Face the true might of the Nathrezim!',14,0,100.0,0,0,0,'Balnazzar - Aggro'),
(10813,1,0,'Damn you mortals! All my plans of revenge, all my hate...I will be avenged...',12,0,100.0,0,0,0,'Balnazzar - Death'),
(11058,0,0,'Looking for these???? You\'ll never have em!',12,0,66.0,0,0,0,'Fras Siabi'),
(11058,0,1,'I\'m going to wear your skin as a smoking jacket! The stogies? You\'ll have to pry them from my cold dead... er... RAWR!!!!',12,0,33.0,0,0,0,'Fras Siabi'),
(11142,0,0,'No tampering with the mail!',12,0,100.0,0,0,0,'Undead Postman'),
(16031,0,0,'You did it... you\'ve slain Baron Rivendare!  The Argent Dawn shall hear of your valiant deeds!',12,0,0.0,0,0,0,'');
